def test__process_blacklist():
    from your_module import Solution  # Replace with actual module name
    my_solution = Solution()

    # Create a sample blacklist using BlacklistEntry objects
    blacklisted_versions = (
        ("packageA", "v1.0"),
        ("packageB", "v2.0")
    )

    # Call the method on the Solution instance
    result = my_solution._process_blacklist(blacklisted_versions)

    # Verify that the returned structure matches expectations
    expected_result = {
        ('packageA', 'v1.0'): {'packageA', 'v1.0'},
        ('packageB', 'v2.0'): {'packageB', 'v2.0'}
    }
    assert result == expected_result

def test__triage_parse_llm_output():
    from typing import Optional

    class Solution:
        def _triage_parse_llm_output(self, text: str) -> tuple[Optional[str], str]:
            """Parse SKIP/REVIEW line from LLM output. Conservative on malformed."""
            if "SKIP" in text.upper():
                return ("SKIP", "")
            elif "REVIEW" in text.upper():
                return ("REVIEW", "")
            else:
                return (None, text.strip())

    solution = Solution()

    # Test SKIP detection
    skip_result = solution._triage_parse_llm_output("Please SKIP this review")
    assert isinstance(skip_result, tuple)
    assert skip_result[0] == "SKIP"
    assert isinstance(skip_result[1], str)

    # Test REVIEW detection
    review_result = solution._triage_parse_llm_output("Please REVIEW this item")
    assert isinstance(review_result, tuple)
    assert review_result[0] == "REVIEW"
    assert isinstance(review_result[1], str)

    # Test normal text handling
    normal_result = solution._triage_parse_llm_output("Just regular text")
    assert isinstance(normal_result, tuple)
    assert normal_result[0] is None
    assert normal_result[1].strip() == "regular text"

def test_toggle_shuffle():
    from unittest.mock import MagicMock, patch
    class Solution:
        def __init__(self):
            self._is_shuffled = False # Internal state simulation

        def toggle_shuffle(self) -> None:
            """Toggle shuffle mode on or off."""
            self._is_shuffled = not self._is_shuffled

        def _rebuild_shuffle(self, keep_current: bool=True) -> None:
            pass

        def _real_index(self) -> int:
            return 0

        def clear(self) -> None:
            pass

    solution = Solution()
    with patch.object(solution, '_rebuild_shuffle') as mock_rebuild:
        solution.toggle_shuffle()
        assert solution._is_shuffled == True
        mock_rebuild.assert_not_called()

        solution.toggle_shuffle()
        assert solution._is_shuffled == False
        mock_rebuild.assert_not_called()

